#include "mspa/psychology/goals.hpp"
#include "mspa/psychology/personality.hpp"
#include <algorithm>
#include <cmath>
namespace mspa {namespace{std::uint64_t next(const AgentPsychState&a){std::uint64_t n=1;for(const auto&g:a.goals)n=std::max(n,g.id.value()+1);return n;}}
Result<GoalId>GoalSystem::add(AgentPsychState&a,ConceptId c,float p)const{return add(a,c,p,0.5f,a.last_processed_time);}Result<GoalId>GoalSystem::add(AgentPsychState&a,ConceptId c,float p,float commit,PsychTime now)const{if(!c.valid()||!std::isfinite(p)||!std::isfinite(commit))return make_error(ErrorCode::InvalidArgument,"invalid goal");GoalState g{};g.id=GoalId(next(a));g.concept_id=c;g.priority=std::clamp(p,0.0f,1.0f);g.commitment=std::clamp(commit,0.0f,1.0f);g.created_at=g.updated_at=now;a.goals.push_back(g);return g.id;}Result<void>GoalSystem::set_status(AgentPsychState&a,GoalId id,GoalStatus s,PsychTime now)const{auto it=std::find_if(a.goals.begin(),a.goals.end(),[&](const auto&g){return g.id==id;});if(it==a.goals.end())return make_error(ErrorCode::InvalidArgument,"goal does not exist");it->status=s;it->updated_at=now;return {};}Result<void>GoalSystem::complete(AgentPsychState&a,GoalId id)const{return set_status(a,id,GoalStatus::Completed,a.last_processed_time);}Result<void>GoalSystem::derive(AgentPsychState&a,const std::vector<GoalSignal>&signals,PsychTime now,std::size_t max_active)const{for(const auto&s:signals){if(!s.concept_id.valid())continue;auto it=std::find_if(a.goals.begin(),a.goals.end(),[&](const auto&g){return g.concept_id==s.concept_id&&(g.status==GoalStatus::Active||g.status==GoalStatus::Suspended);});if(it==a.goals.end()){auto r=add(a,s.concept_id,s.strength,s.commitment,now);if(!r)return *r.error_if();}else{it->priority=std::clamp(std::max(it->priority,s.strength),0.0f,1.0f);it->commitment=std::clamp(std::max(it->commitment,s.commitment),0.0f,1.0f);it->status=GoalStatus::Active;it->updated_at=now;}}std::vector<GoalState*> active;for(auto&g:a.goals)if(g.status==GoalStatus::Active)active.push_back(&g);std::stable_sort(active.begin(),active.end(),[](auto*x,auto*y){return x->priority>y->priority;});for(std::size_t i=max_active;i<active.size();++i)active[i]->status=GoalStatus::Suspended;return {};}void GoalSystem::decay(AgentPsychState&a,PsychTime now,float rate)const noexcept{const auto pd=PersonalitySystem{}.derive(a.personality);for(auto&g:a.goals){if(g.status!=GoalStatus::Active||now<g.updated_at)continue;float dt=static_cast<float>(now.ticks()-g.updated_at.ticks());g.priority=std::max(0.0f,g.priority-dt*std::max(0.0f,rate)*(1.0f-0.7f*pd.goal_persistence));g.updated_at=now;if(g.priority<=0.001f)g.status=GoalStatus::Abandoned;}}}
